WITH cleaned AS (SELECT id, quantity, ROUND(quantity, 2) AS quantity_rounded FROM inventory WHERE product_id = 3) SELECT CASE WHEN quantity_rounded >= 80 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_rounded_tier, BIT_OR(quantity) AS quantity_bit_or, MIN(quantity) AS min_quantity, SUM(quantity) AS total_quantity, BIT_AND(quantity) AS quantity_bit_and, MIN(quantity_rounded) AS min_quantity_rounded, APPROX_PERCENTILE(quantity_rounded, ARRAY(0.25, 0.5, 0.75)) AS quantity_rounded_quartiles FROM cleaned GROUP BY quantity_rounded_tier ORDER BY min_quantity_rounded DESC;
